-- Explanations only. Every update checks the prior revision and exact data. Retain question history.
UPDATE public_questions SET data='{"id":"community-d971de46-3a05-4f24-a907-2a0363fed5e3-1","category":"作業系統基礎","type":"多選題","stem":"What data structures are common in the kernel?","options":["Array","Doubly linked list","Binary search tree","Circular linked list"],"answer":"B、C、D","explanation":"雙向鏈結串列可在已知節點的位置快速插入、刪除，並雙向走訪；環狀鏈結串列適合輪流處理工作；二元搜尋樹可依鍵值建立查找順序。這些都是核心可採用的資料結構。\n\n陣列同樣常見於核心，例如固定索引表與緩衝區，不能解釋成核心不使用陣列。本題保留現有答案，但題幹只問「常見資料結構」，沒有提供排除陣列的條件；這是答案與題意範圍的差異。","choiceKey":"BCD","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":"","submissionReview":{"status":"resolved","reason":"題幹符合，但選項不同；請核對是否抄漏或為不同版本。","references":["basics-31"],"createdAt":1793460194749,"resolvedAt":1794999280940}}',revision=revision+1,updated_at=1795706845210 WHERE id='community-d971de46-3a05-4f24-a907-2a0363fed5e3-1' AND revision=2 AND data='{"id":"community-d971de46-3a05-4f24-a907-2a0363fed5e3-1","category":"作業系統基礎","type":"多選題","stem":"What data structures are common in the kernel?","options":["Array","Doubly linked list","Binary search tree","Circular linked list"],"answer":"B、C、D","explanation":"","choiceKey":"BCD","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":"","submissionReview":{"status":"resolved","reason":"題幹符合，但選項不同；請核對是否抄漏或為不同版本。","references":["basics-31"],"createdAt":1793460194749,"resolvedAt":1794999280940}}' AND EXISTS (SELECT 1 FROM question_history WHERE id='23771015-d58d-4d22-8078-c15388856a2e');
UPDATE public_questions SET data='{"id":"community-b5fa3636-bfa3-4439-80ab-b63b02f97307-6","category":"作業系統基礎","type":"多選題","stem":"中斷 (Interrupt) 的常見類型包含？","options":["Software interrupt (Trap/Exception)","Error-generated","Networkr-request generated","Timer interrupt"],"answer":"A、B","explanation":"軟體中斷由程式指令主動引發，例如請求系統服務；錯誤產生的例外則可由除以零、非法指令等同步事件引發。這兩類事件都與目前執行的指令有關，但名稱及分類會因處理器架構而異。\n\n計時器到期與網路介面收到封包也可以觸發硬體中斷。因此，若題幹泛指所有常見中斷，這兩種硬體事件也符合；若只限目前指令引發的同步事件，才可排除它們。原題沒有明列這個限制，現有答案維持不變，不能據此認為計時器或網路不會造成中斷。","choiceKey":"AB","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":"","submissionReview":{"status":"resolved","reason":"題幹對到多道既有題目，請確認應保留的版本","references":["basics-8","basics-9"],"createdAt":1793341006923,"resolvedAt":1794999621992}}',revision=revision+1,updated_at=1795706845210 WHERE id='community-b5fa3636-bfa3-4439-80ab-b63b02f97307-6' AND revision=2 AND data='{"id":"community-b5fa3636-bfa3-4439-80ab-b63b02f97307-6","category":"作業系統基礎","type":"多選題","stem":"中斷 (Interrupt) 的常見類型包含？","options":["Software interrupt (Trap/Exception)","Error-generated","Networkr-request generated","Timer interrupt"],"answer":"A、B","explanation":"","choiceKey":"AB","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":"","submissionReview":{"status":"resolved","reason":"題幹對到多道既有題目，請確認應保留的版本","references":["basics-8","basics-9"],"createdAt":1793341006923,"resolvedAt":1794999621992}}' AND EXISTS (SELECT 1 FROM question_history WHERE id='ec6dc628-330e-4cfa-9458-170805fe5b3d');
UPDATE public_questions SET data='{"id":"community-eb1592ba-0e1e-47b2-a83d-0c7992445ee9-6","category":"作業系統架構","type":"多選題","stem":"Which facilities are commonly provided by background services or daemons?","options":["Process scheduling","Error logging","Disk checking","Web browser frontend layout"],"answer":"A、B、C","explanation":"錯誤記錄服務可在背景收集系統日誌；磁碟檢查可由背景服務安排與執行。兩者都是不需使用者持續操作的系統工作。瀏覽器前端排版則屬瀏覽器呈現網頁的工作，不屬於此處的背景系統服務。\n\n「Process scheduling」需要區分層次：安排背景工作何時啟動，可以由服務程式負責；決定下一個取得 CPU 的程序，則主要由核心排程器執行。現有答案包含這一項，但原題沒有說明是哪種排程，不能把核心 CPU 排程器等同於一般 daemon。","choiceKey":"ABC","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}',revision=revision+1,updated_at=1795706845210 WHERE id='community-eb1592ba-0e1e-47b2-a83d-0c7992445ee9-6' AND revision=1 AND data='{"id":"community-eb1592ba-0e1e-47b2-a83d-0c7992445ee9-6","category":"作業系統架構","type":"多選題","stem":"Which facilities are commonly provided by background services or daemons?","options":["Process scheduling","Error logging","Disk checking","Web browser frontend layout"],"answer":"A、B、C","explanation":"","choiceKey":"ABC","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}' AND EXISTS (SELECT 1 FROM question_history WHERE id='af8dc495-b497-4f22-8814-a3a42c68679c');
UPDATE public_questions SET data='{"id":"community-e9945852-7bb0-4512-a4ed-d4bd8fa5e297-2","category":"程序與 IPC","type":"填空題","stem":"A process is organized into several parts in memory, where the ____________ contains temporary data such as function parameters, return addresses, and local variables. (Please answer using English abbreviations and uppercase letters.)","options":[],"answer":"PCB","explanation":"函式呼叫時，stack（堆疊）上的呼叫框架通常保存參數、回傳位址與自動區域變數；函式返回後，該框架即可回收。這是題幹 temporary data 所描述的用途。\n\nPCB（Process Control Block）則是核心記錄程序狀態與資源的控制結構，可能保存堆疊指標，但不是存放整份函式呼叫資料的區域。現有答案 PCB 維持不變；它與題幹的標準記憶體區域名稱存在差異，兩者的用途需分開理解。","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}',revision=revision+1,updated_at=1795706845210 WHERE id='community-e9945852-7bb0-4512-a4ed-d4bd8fa5e297-2' AND revision=1 AND data='{"id":"community-e9945852-7bb0-4512-a4ed-d4bd8fa5e297-2","category":"程序與 IPC","type":"填空題","stem":"A process is organized into several parts in memory, where the ____________ contains temporary data such as function parameters, return addresses, and local variables. (Please answer using English abbreviations and uppercase letters.)","options":[],"answer":"PCB","explanation":"","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}' AND EXISTS (SELECT 1 FROM question_history WHERE id='0ec879a3-8863-4126-be1a-520363049d04');
UPDATE public_questions SET data='{"id":"community-9e5559de-2377-43bf-8d2f-e124e2aa2bd1-2","category":"程序與 IPC","type":"多選題","stem":"以下哪些是遠端程序呼叫（RPC）的特點？","options":["使用樁（stubs）來定位伺服器並封送參數","使用外部資料表示法（XDL）格式處理資料","抽象化了網路系統中的程序呼叫","需要親屬關係"],"answer":"A、B、C","explanation":"RPC 讓客戶端以類似本地函式呼叫的方式使用遠端服務。stub 負責封送參數、傳送請求及接收結果，隱藏部分網路通訊細節；客戶端與伺服器不必具有父子或其他親屬關係，所以「需要親屬關係」不符合 RPC 的一般條件。\n\n跨平台傳送資料時，需要約定資料編碼。ONC／Sun RPC 採用 XDR（External Data Representation），但其他 RPC 系統可以使用不同格式。原選項寫的是 XDL，與 XDR 不同；現有選項及答案均保留，此處指出術語差異，不把 XDL 當成 XDR 的正式縮寫。","choiceKey":"ABC","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":"","submissionReview":{"status":"resolved","reason":"題幹相同，但題型不同","references":["process-86"],"createdAt":1793419256443,"resolvedAt":1794999330935}}',revision=revision+1,updated_at=1795706845210 WHERE id='community-9e5559de-2377-43bf-8d2f-e124e2aa2bd1-2' AND revision=2 AND data='{"id":"community-9e5559de-2377-43bf-8d2f-e124e2aa2bd1-2","category":"程序與 IPC","type":"多選題","stem":"以下哪些是遠端程序呼叫（RPC）的特點？","options":["使用樁（stubs）來定位伺服器並封送參數","使用外部資料表示法（XDL）格式處理資料","抽象化了網路系統中的程序呼叫","需要親屬關係"],"answer":"A、B、C","explanation":"","choiceKey":"ABC","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":"","submissionReview":{"status":"resolved","reason":"題幹相同，但題型不同","references":["process-86"],"createdAt":1793419256443,"resolvedAt":1794999330935}}' AND EXISTS (SELECT 1 FROM question_history WHERE id='803d5a1d-025b-4e84-a03d-8d1776a9c520');
UPDATE public_questions SET data='{"id":"community-7194cbec-f4e8-4431-b237-d8864d7ca8ea-4","category":"執行緒與多執行緒","type":"多選題","stem":"Which multithreading model allows a single kernel thread to be bound to a single user thread?","options":["One-to-One","Many-to-One","Two-level","Many-to-Many"],"answer":"A、B、C、D","explanation":"One-to-One 讓每條使用者執行緒對應一條核心執行緒；Many-to-One 讓多條使用者執行緒共用一條核心執行緒；Many-to-Many 在兩組執行緒之間進行多對多映射。Two-level 在多對多模型上增加指定綁定能力，可讓某條使用者執行緒固定綁定某條核心執行緒。\n\n判斷關鍵是「固定綁定」與「當下由某條核心執行緒承載」不同。若 bound 指可指定固定綁定，四種模型並非全部具有相同能力。現有全選答案保留，但原題的 bound 用法與模型分類存在範圍差異，不能因此把四種映射機制視為相同。","choiceKey":"ABCD","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":"","submissionReview":{"status":"resolved","reason":"題幹相同，但題型不同","references":["threads-018"],"createdAt":1793351127539,"resolvedAt":1794999337207}}',revision=revision+1,updated_at=1795706845210 WHERE id='community-7194cbec-f4e8-4431-b237-d8864d7ca8ea-4' AND revision=2 AND data='{"id":"community-7194cbec-f4e8-4431-b237-d8864d7ca8ea-4","category":"執行緒與多執行緒","type":"多選題","stem":"Which multithreading model allows a single kernel thread to be bound to a single user thread?","options":["One-to-One","Many-to-One","Two-level","Many-to-Many"],"answer":"A、B、C、D","explanation":"","choiceKey":"ABCD","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":"","submissionReview":{"status":"resolved","reason":"題幹相同，但題型不同","references":["threads-018"],"createdAt":1793351127539,"resolvedAt":1794999337207}}' AND EXISTS (SELECT 1 FROM question_history WHERE id='277a3a36-e815-4ae6-b8e1-446c52167a30');
UPDATE public_questions SET data='{"id":"community-2aa0ecfb-6355-4e00-bd7a-6bfc5023d145-1","category":"執行緒與多執行緒","type":"多選題","stem":"哪一種多執行緒模型允許一個核心執行緒與一個使用者執行緒綁定？","options":["Many-to-One","Two-level","One-to-One","Many-to-Many"],"answer":"A、B、C、D","explanation":"One-to-One 讓每條使用者執行緒對應一條核心執行緒；Many-to-One 讓多條使用者執行緒共用一條核心執行緒；Many-to-Many 允許多條使用者執行緒在一組核心執行緒上執行。Two-level 則在多對多模型之外，允許指定某條使用者執行緒與某條核心執行緒固定綁定。\n\n「可以固定綁定」不是「某個時刻只有一條使用者執行緒正在核心執行緒上執行」。若題目問的是前者，各模型的能力不同；現有全選答案維持不變，理解時應保留這項差異，避免由答案推成四種模型完全等價。","choiceKey":"ABCD","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":"","submissionReview":{"status":"resolved","reason":"題幹相同，但題型不同","references":["threads-018"],"createdAt":1793351171641,"resolvedAt":1794999336153}}',revision=revision+1,updated_at=1795706845210 WHERE id='community-2aa0ecfb-6355-4e00-bd7a-6bfc5023d145-1' AND revision=2 AND data='{"id":"community-2aa0ecfb-6355-4e00-bd7a-6bfc5023d145-1","category":"執行緒與多執行緒","type":"多選題","stem":"哪一種多執行緒模型允許一個核心執行緒與一個使用者執行緒綁定？","options":["Many-to-One","Two-level","One-to-One","Many-to-Many"],"answer":"A、B、C、D","explanation":"","choiceKey":"ABCD","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":"","submissionReview":{"status":"resolved","reason":"題幹相同，但題型不同","references":["threads-018"],"createdAt":1793351171641,"resolvedAt":1794999336153}}' AND EXISTS (SELECT 1 FROM question_history WHERE id='723e4a14-7e1e-44a8-8a22-e65f8047394a');
UPDATE public_questions SET data='{"id":"community-c8fd251c-2f96-418c-b6ec-ce209abb0975-1","category":"CPU 排程","type":"多選題","stem":"What methods can be used to estimate the length of the next CPU burst?","options":["Setting α=1 to only consider the last burst","Asking the user","Using exponential averaging of previous CPU bursts","Using a constant value"],"answer":"A、B、C","explanation":"指數平均以 τ(next)=α·t(last)+(1−α)·τ(current) 預測下一次 CPU burst，將最近實測時間與先前預測加權。例如 α=0.5、最近 burst 為 8、舊預測為 4，下一次預測就是 6。\n\n令 α=1 時，新預測等於最近一次 burst，完全忽略更早資料；這是指數平均的特例。詢問使用者也能取得估計值，但通常不如歷史量測可靠。固定值則是沒有依歷史調整的基準預測，並非不能當估計。現有答案排除固定值，原題未明示要排除這種基準方法，需留意這個範圍。","choiceKey":"ABC","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}',revision=revision+1,updated_at=1795706845210 WHERE id='community-c8fd251c-2f96-418c-b6ec-ce209abb0975-1' AND revision=1 AND data='{"id":"community-c8fd251c-2f96-418c-b6ec-ce209abb0975-1","category":"CPU 排程","type":"多選題","stem":"What methods can be used to estimate the length of the next CPU burst?","options":["Setting α=1 to only consider the last burst","Asking the user","Using exponential averaging of previous CPU bursts","Using a constant value"],"answer":"A、B、C","explanation":"","choiceKey":"ABC","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}' AND EXISTS (SELECT 1 FROM question_history WHERE id='c2c3eaa4-c466-458b-93cd-674d27a93a99');
UPDATE public_questions SET data='{"id":"community-c57ffcbc-2e7b-48df-aa41-7ffc2512ffd0-1","category":"CPU 排程","type":"單選題","stem":"How is aging implemented in Multilevel Feedback Queue scheduling?","options":["By reducing the number of queues for a process","By increasing the waiting time","By giving each process a fixed time quantum","By allowing a process to move between queues"],"answer":"D","explanation":"Aging 的目的，是避免低優先權工作長期等不到 CPU。多層回饋佇列可記錄等待時間，讓等待過久的程序移到較高優先權佇列，或定期把工作提升，增加它被排到的機會。因此關鍵是允許程序在佇列間移動，而且移動方向及時機要有助於久候工作。\n\n只增加等待時間會讓飢餓更嚴重；固定時間片只決定一次可執行多久，不能單獨保證低優先權工作獲得服務；減少某個程序的佇列數也不是 aging 的核心機制。","choiceKey":"D","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}',revision=revision+1,updated_at=1795706845211 WHERE id='community-c57ffcbc-2e7b-48df-aa41-7ffc2512ffd0-1' AND revision=1 AND data='{"id":"community-c57ffcbc-2e7b-48df-aa41-7ffc2512ffd0-1","category":"CPU 排程","type":"單選題","stem":"How is aging implemented in Multilevel Feedback Queue scheduling?","options":["By reducing the number of queues for a process","By increasing the waiting time","By giving each process a fixed time quantum","By allowing a process to move between queues"],"answer":"D","explanation":"","choiceKey":"D","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}' AND EXISTS (SELECT 1 FROM question_history WHERE id='dbc6e463-7c98-487f-9df1-509769ad885f');
UPDATE public_questions SET data='{"id":"community-70c0705f-a1d7-4e2e-b00f-a94d9b435d25-8","category":"挖寶單元","type":"填空題","stem":"即時排程 問題\n\n已知有兩個行程 P1 P2 分別需要的 CPU 、deladline 時間如下\n\nPeriod Deadline CPU\nP1 50 50 20\nP2 100 100 35\n\n若使用 Rate Monotonic 方式 P2 的第一塊資料 最後完成的位置 在哪一個時間點 ____________ 之前 (請給最接見的時間 數字)","options":[],"answer":"(80)","explanation":"Rate Monotonic 以週期較短者為高優先權，所以 P1 的優先權高於 P2。假設兩者在時間 0 同時釋出第一個工作、採可搶佔單處理器排程，時間線如下：\n0–20：P1 執行 20，完成第一份工作。\n20–50：P2 執行 30，還剩 5。\n50–70：P1 第二份工作到達並搶佔，執行 20。\n70–75：P2 完成剩下的 5，因此第一份工作在 75 完成。\n\n現有填答為 (80)。75 確實在 80 之前，但若「最接近的時間」要求精確完成時點，計算結果是 75。原題未交代時間刻度是否只能以十為單位，答案維持不變，不能憑空把完成時點延後到 80。","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}',revision=revision+1,updated_at=1795706845211 WHERE id='community-70c0705f-a1d7-4e2e-b00f-a94d9b435d25-8' AND revision=1 AND data='{"id":"community-70c0705f-a1d7-4e2e-b00f-a94d9b435d25-8","category":"挖寶單元","type":"填空題","stem":"即時排程 問題\n\n已知有兩個行程 P1 P2 分別需要的 CPU 、deladline 時間如下\n\nPeriod Deadline CPU\nP1 50 50 20\nP2 100 100 35\n\n若使用 Rate Monotonic 方式 P2 的第一塊資料 最後完成的位置 在哪一個時間點 ____________ 之前 (請給最接見的時間 數字)","options":[],"answer":"(80)","explanation":"","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}' AND EXISTS (SELECT 1 FROM question_history WHERE id='765e2cf5-48f0-4ad7-895c-9dcdf63f8633');
UPDATE public_questions SET data='{"id":"community-49eea5c8-6d64-4681-8f6f-5d3b0f8fa453-2","category":"L8 · 死結","type":"填空題","stem":"為了打破死結,一種方法是通過 ____________ 來終止一個或多個進程。(請用小寫英文回答)","options":[],"answer":"preemption","explanation":"死結恢復常見兩種做法：終止程序，或搶佔資源。Process termination 直接終止一個或多個程序，回收它們持有的資源；resource preemption 則強制取回可回收資源，必要時讓受影響的程序回滾並重新執行。\n\n現有答案 preemption 保留，但原題使用「終止一個或多個進程」，其字面對應的是 process termination。資源被搶佔並不必然代表整個程序被終止，作答與觀念理解要分清楚這兩種恢復動作。","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}',revision=revision+1,updated_at=1795706845211 WHERE id='community-49eea5c8-6d64-4681-8f6f-5d3b0f8fa453-2' AND revision=1 AND data='{"id":"community-49eea5c8-6d64-4681-8f6f-5d3b0f8fa453-2","category":"L8 · 死結","type":"填空題","stem":"為了打破死結,一種方法是通過 ____________ 來終止一個或多個進程。(請用小寫英文回答)","options":[],"answer":"preemption","explanation":"無","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}' AND EXISTS (SELECT 1 FROM question_history WHERE id='9aeda127-f623-4cee-a9c4-80e9dd8fb567');
