INSERT INTO question_history (id,question_id,revision,course,unit,data,is_published,action,actor,note,created_at) SELECT '23771015-d58d-4d22-8078-c15388856a2e',id,revision,course,unit,data,is_published,'update','owner-requested','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變',1795706845210 FROM public_questions WHERE id='community-d971de46-3a05-4f24-a907-2a0363fed5e3-1' AND revision=2 AND data='{"id":"community-d971de46-3a05-4f24-a907-2a0363fed5e3-1","category":"作業系統基礎","type":"多選題","stem":"What data structures are common in the kernel?","options":["Array","Doubly linked list","Binary search tree","Circular linked list"],"answer":"B、C、D","explanation":"","choiceKey":"BCD","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":"","submissionReview":{"status":"resolved","reason":"題幹符合，但選項不同；請核對是否抄漏或為不同版本。","references":["basics-31"],"createdAt":1793460194749,"resolvedAt":1794999280940}}';
