INSERT INTO question_history (id,question_id,revision,course,unit,data,is_published,action,actor,note,created_at) SELECT 'af8dc495-b497-4f22-8814-a3a42c68679c',id,revision,course,unit,data,is_published,'update','owner-requested','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變',1795706845210 FROM public_questions WHERE id='community-eb1592ba-0e1e-47b2-a83d-0c7992445ee9-6' AND revision=1 AND data='{"id":"community-eb1592ba-0e1e-47b2-a83d-0c7992445ee9-6","category":"作業系統架構","type":"多選題","stem":"Which facilities are commonly provided by background services or daemons?","options":["Process scheduling","Error logging","Disk checking","Web browser frontend layout"],"answer":"A、B、C","explanation":"","choiceKey":"ABC","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}';
INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT 'ec32d5ef-dd52-42c5-9ddb-0b535f8e921e','os','process-8',3,'{"category":"Process 基礎","stem":"一個程序在記憶體中被組織成多個部分,其中 ____________ 包含暫時性資料,如函式參數、回傳位址和區域變數。(請用英文縮寫回答 且用大寫字母)","options":[],"answer":"PCB","translation":"","note":"","explanation":"PCB（Process Control Block）記錄程序識別、執行狀態、暫存器、排程與記憶體管理資訊，讓作業系統能暫停並恢復程序；其中可能包含堆疊指標。\n\n函式參數、回傳位址與一般自動區域變數，通常保存在 stack（堆疊）的呼叫框架。呼叫函式時建立框架，返回後回收，可用這個過程辨認題幹描述的區域。現有答案 PCB 保留，但它與題幹描述的 stack 不一致；不能把「PCB 保存堆疊位置」理解成「所有區域變數都存於 PCB」。","terms":[{"keys":["process","程序","行程"],"label":"Process（程序）","text":"正在執行中的程式；它需要 CPU、記憶體與 I/O 資源。"}],"id":"process-8","answerProvided":true,"aliases":[],"imageKeys":[],"images":[],"type":"填空題","optionTranslations":[],"originalAnswer":"stack（堆疊）"}','{"category":"Process 基礎","stem":"一個程序在記憶體中被組織成多個部分,其中 ____________ 包含暫時性資料,如函式參數、回傳位址和區域變數。(請用英文縮寫回答 且用大寫字母)","options":[],"answer":"PCB","translation":"","note":"","explanation":"PCB 是作業系統記錄程序狀態的資料結構，不是這些暫時資料的記憶體區段。","terms":[{"keys":["process","程序","行程"],"label":"Process（程序）","text":"正在執行中的程式；它需要 CPU、記憶體與 I/O 資源。"}],"id":"process-8","answerProvided":true,"aliases":[],"imageKeys":[],"images":[],"type":"填空題","optionTranslations":[],"originalAnswer":"stack（堆疊）"}','2f842a3a4e472340af468e4d9b6c517d71f6c2317248d539e0973ba5fbf43f46','update','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變','owner-requested',1795706845210 WHERE COALESCE((SELECT MAX(revision) FROM builtin_question_edits WHERE course='os' AND question_id='process-8'),0)=2 AND EXISTS (SELECT 1 FROM builtin_question_edits WHERE id='c366340f-ef1c-4b85-ba7b-87026a6a8d41' AND data='{"category":"Process 基礎","stem":"一個程序在記憶體中被組織成多個部分,其中 ____________ 包含暫時性資料,如函式參數、回傳位址和區域變數。(請用英文縮寫回答 且用大寫字母)","options":[],"answer":"PCB","translation":"","note":"","explanation":"PCB 是作業系統記錄程序狀態的資料結構，不是這些暫時資料的記憶體區段。","terms":[{"keys":["process","程序","行程"],"label":"Process（程序）","text":"正在執行中的程式；它需要 CPU、記憶體與 I/O 資源。"}],"id":"process-8","answerProvided":true,"aliases":[],"imageKeys":[],"images":[],"type":"填空題","optionTranslations":[],"originalAnswer":"stack（堆疊）"}');
