INSERT INTO question_history (id,question_id,revision,course,unit,data,is_published,action,actor,note,created_at) SELECT '9aeda127-f623-4cee-a9c4-80e9dd8fb567',id,revision,course,unit,data,is_published,'update','owner-requested','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變',1795706845211 FROM public_questions WHERE id='community-49eea5c8-6d64-4681-8f6f-5d3b0f8fa453-2' AND revision=1 AND data='{"id":"community-49eea5c8-6d64-4681-8f6f-5d3b0f8fa453-2","category":"L8 · 死結","type":"填空題","stem":"為了打破死結,一種方法是通過 ____________ 來終止一個或多個進程。(請用小寫英文回答)","options":[],"answer":"preemption","explanation":"無","imageKeys":[],"answerProvided":true,"images":[],"translation":"","terms":[],"note":""}';
INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT 'c759d747-0e93-4387-88ec-c5bb436ce77d','algorithms','L2-025',1,'{"category":"函數增長率 / Log","type":"複選題","q":"對於所有 x > -1，下列關於對數函數（Logarithm）的數學不等式哪些是正確的？","a":"A、B、D","opts":["A. x / (1 + x) <= ln(1 + x)","B. ln(1 + x) < x","C. ln(1 + x) > x","D. ln(1 + x) = x - x^2/2 + x^3/3 - x^4/4 + ... (|x| < 1)"],"ex":"令 g(x)=x−ln(1+x)，則 g′(x)=x/(1+x)。在 −1<x<0 時遞減，在 x>0 時遞增，且 g(0)=0，所以 ln(1+x)≤x，只有 x=0 取等號。「嚴格小於 x」因此不能對所有 x>−1 成立，而「大於 x」也不成立。\n\n再令 h(x)=ln(1+x)−x/(1+x)，h′(x)=x/(1+x)²，同樣在 x=0 取得最小值 0，所以 x/(1+x)≤ln(1+x) 成立。\n\n級數 x−x²/2+x³/3−… 在選項所註 |x|<1 範圍內等於 ln(1+x)，不能把級數直接套到整個 x>−1。現有答案保留；其中嚴格不等號在 x=0 的反例，以及各選項的適用區間，都需要分別檢查。","exact":false,"warn":false,"sources":["algorithm-analysis"],"answerProvided":true,"bookmarkId":"L2-025","aliases":[],"imageKeys":[],"images":[],"explanation":"令 g(x)=x−ln(1+x)，則 g′(x)=x/(1+x)。在 −1<x<0 時遞減，在 x>0 時遞增，且 g(0)=0，所以 ln(1+x)≤x，只有 x=0 取等號。「嚴格小於 x」因此不能對所有 x>−1 成立，而「大於 x」也不成立。\n\n再令 h(x)=ln(1+x)−x/(1+x)，h′(x)=x/(1+x)²，同樣在 x=0 取得最小值 0，所以 x/(1+x)≤ln(1+x) 成立。\n\n級數 x−x²/2+x³/3−… 在選項所註 |x|<1 範圍內等於 ln(1+x)，不能把級數直接套到整個 x>−1。現有答案保留；其中嚴格不等號在 x=0 的反例，以及各選項的適用區間，都需要分別檢查。"}','{"category":"函數增長率 / Log","type":"複選題","q":"對於所有 x > -1，下列關於對數函數（Logarithm）的數學不等式哪些是正確的？","a":"A、B、D","opts":["A. x / (1 + x) <= ln(1 + x)","B. ln(1 + x) < x","C. ln(1 + x) > x","D. ln(1 + x) = x - x^2/2 + x^3/3 - x^4/4 + ... (|x| < 1)"],"ex":"依原題庫答案選 A、B、D。","exact":false,"warn":false,"sources":["algorithm-analysis"],"answerProvided":true,"bookmarkId":"L2-025","aliases":[],"imageKeys":[],"images":[]}','d6f89bfa86ce5cd21af3fd3d7d3738a40ce34168c4c15d3c9e6c6f755035cb8d','update','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變','owner-requested',1795706845211 WHERE COALESCE((SELECT MAX(revision) FROM builtin_question_edits WHERE course='algorithms' AND question_id='L2-025'),0)=0;
INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT '37e68217-6389-4326-abff-45b1724f9e64','algorithms','L2-026',2,'{"category":"函數增長率 / Log","type":"多選題","q":"對於所有實數 x，下列關於指數函數的性質哪些是正確的？","a":"A、C、D","opts":["當 n 趨向無窮大時，lim (1 + x/n)ⁿ = eˣ","eˣ 永遠小於 1","當 |x| <= 1 時，eˣ <= 1 + x + x²/2","1 + x <= eˣ"],"ex":"固定實數 x，當 n 趨向無窮大時，(1+x/n)ⁿ 趨近 eˣ。另由指數函數的凸性，曲線不低於 x=0 處的切線，所以 1+x≤eˣ，等號只在 x=0 成立。\n\n「eˣ 永遠小於 1」不成立，代入 x=1 即得 e>1。「|x|≤1 時 eˣ≤1+x+x²/2」也不對整個區間成立：x=1 時，左邊約 2.718，右邊為 2.5。從泰勒展開看，正的 x 還有 x³/6 等正項，不能把二次截斷直接當上界。\n\n現有答案維持不變；包含二次上界的選項與這個反例有差異，不能將其作為所有 |x|≤1 都適用的公式。","exact":false,"warn":false,"sources":["algorithm-analysis"],"answerProvided":true,"bookmarkId":"L2-026","stem":"對於所有實數 x，下列關於指數函數的性質哪些是正確的？","options":["當 n 趨向無窮大時，lim (1 + x/n)ⁿ = eˣ","eˣ 永遠小於 1","當 |x| <= 1 時，eˣ <= 1 + x + x²/2","1 + x <= eˣ"],"answer":"A、C、D","explanation":"固定實數 x，當 n 趨向無窮大時，(1+x/n)ⁿ 趨近 eˣ。另由指數函數的凸性，曲線不低於 x=0 處的切線，所以 1+x≤eˣ，等號只在 x=0 成立。\n\n「eˣ 永遠小於 1」不成立，代入 x=1 即得 e>1。「|x|≤1 時 eˣ≤1+x+x²/2」也不對整個區間成立：x=1 時，左邊約 2.718，右邊為 2.5。從泰勒展開看，正的 x 還有 x³/6 等正項，不能把二次截斷直接當上界。\n\n現有答案維持不變；包含二次上界的選項與這個反例有差異，不能將其作為所有 |x|≤1 都適用的公式。","images":[],"choiceKey":"ACD","translation":"","optionTranslations":[],"note":"","imageKeys":[]}','{"category":"函數增長率 / Log","type":"多選題","q":"對於所有實數 x，下列關於指數函數的性質哪些是正確的？","a":"A、C、D","opts":["當 n 趨向無窮大時，lim (1 + x/n)ⁿ = eˣ","eˣ 永遠小於 1","當 |x| <= 1 時，eˣ <= 1 + x + x²/2","1 + x <= eˣ"],"ex":"eˣ≥1+x 對所有實數 x 成立，在 x＝0 取等號；固定 x 時，limₙ→∞(1+x/n)ⁿ＝eˣ 也成立。eˣ 並非永遠小於 1，例如 x＝1 時 e>1。\n\n老師答案保留，但「|x|≤1 時 eˣ≤1+x+x²/2」照原式並不對所有該區間的 x 成立：取 x＝1，左邊約 2.718，右邊為 2.5，直接得到反例。當 0<x≤1，泰勒展開還有正的 x³/6 等項，不能用二次截斷式作這種上界。若要成立，需另補適當條件或餘項界；解析不把錯誤不等式當成通則。","exact":false,"warn":false,"sources":["algorithm-analysis"],"answerProvided":true,"bookmarkId":"L2-026","stem":"對於所有實數 x，下列關於指數函數的性質哪些是正確的？","options":["當 n 趨向無窮大時，lim (1 + x/n)ⁿ = eˣ","eˣ 永遠小於 1","當 |x| <= 1 時，eˣ <= 1 + x + x²/2","1 + x <= eˣ"],"answer":"A、C、D","explanation":"eˣ≥1+x 對所有實數 x 成立，在 x＝0 取等號；固定 x 時，limₙ→∞(1+x/n)ⁿ＝eˣ 也成立。eˣ 並非永遠小於 1，例如 x＝1 時 e>1。\n\n老師答案保留，但「|x|≤1 時 eˣ≤1+x+x²/2」照原式並不對所有該區間的 x 成立：取 x＝1，左邊約 2.718，右邊為 2.5，直接得到反例。當 0<x≤1，泰勒展開還有正的 x³/6 等項，不能用二次截斷式作這種上界。若要成立，需另補適當條件或餘項界；解析不把錯誤不等式當成通則。","images":[],"choiceKey":"ACD","translation":"","optionTranslations":[],"note":"","imageKeys":[]}','c0df2abbc56a0b45f289f7d854e9e3ec81dde577345380ee89708709aea7edbe','update','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變','owner-requested',1795706845211 WHERE COALESCE((SELECT MAX(revision) FROM builtin_question_edits WHERE course='algorithms' AND question_id='L2-026'),0)=1 AND EXISTS (SELECT 1 FROM builtin_question_edits WHERE id='42fca421-21b5-4c86-a7a6-209a10b1fd37' AND data='{"category":"函數增長率 / Log","type":"多選題","q":"對於所有實數 x，下列關於指數函數的性質哪些是正確的？","a":"A、C、D","opts":["當 n 趨向無窮大時，lim (1 + x/n)ⁿ = eˣ","eˣ 永遠小於 1","當 |x| <= 1 時，eˣ <= 1 + x + x²/2","1 + x <= eˣ"],"ex":"eˣ≥1+x 對所有實數 x 成立，在 x＝0 取等號；固定 x 時，limₙ→∞(1+x/n)ⁿ＝eˣ 也成立。eˣ 並非永遠小於 1，例如 x＝1 時 e>1。\n\n老師答案保留，但「|x|≤1 時 eˣ≤1+x+x²/2」照原式並不對所有該區間的 x 成立：取 x＝1，左邊約 2.718，右邊為 2.5，直接得到反例。當 0<x≤1，泰勒展開還有正的 x³/6 等項，不能用二次截斷式作這種上界。若要成立，需另補適當條件或餘項界；解析不把錯誤不等式當成通則。","exact":false,"warn":false,"sources":["algorithm-analysis"],"answerProvided":true,"bookmarkId":"L2-026","stem":"對於所有實數 x，下列關於指數函數的性質哪些是正確的？","options":["當 n 趨向無窮大時，lim (1 + x/n)ⁿ = eˣ","eˣ 永遠小於 1","當 |x| <= 1 時，eˣ <= 1 + x + x²/2","1 + x <= eˣ"],"answer":"A、C、D","explanation":"eˣ≥1+x 對所有實數 x 成立，在 x＝0 取等號；固定 x 時，limₙ→∞(1+x/n)ⁿ＝eˣ 也成立。eˣ 並非永遠小於 1，例如 x＝1 時 e>1。\n\n老師答案保留，但「|x|≤1 時 eˣ≤1+x+x²/2」照原式並不對所有該區間的 x 成立：取 x＝1，左邊約 2.718，右邊為 2.5，直接得到反例。當 0<x≤1，泰勒展開還有正的 x³/6 等項，不能用二次截斷式作這種上界。若要成立，需另補適當條件或餘項界；解析不把錯誤不等式當成通則。","images":[],"choiceKey":"ACD","translation":"","optionTranslations":[],"note":"","imageKeys":[]}');
INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT '8c02cff9-56dd-4dfc-8c49-1357109bd256','algorithms','L3-035',5,'{"category":"大師定理","type":"多選題","q":"大師定理 Case 3 的條件包含？","a":"A、B、C","ex":"對 T(n)=aT(n/b)+f(n)，先令 p=log_b a。Case 3 要求 a≥1、b>1 為常數，且存在 ε>0，使 f(n)=Ω(n^(p+ε))；還需規則性條件：存在 c<1，使 a·f(n/b)≤c·f(n) 對足夠大的 n 成立，才能得到 T(n)=Θ(f(n))。\n\n例如 2T(n/2)+n²，p=1，n² 比 n 多一個正次方，且 2(n/2)²=n²/2，符合規則性條件，因此為 Θ(n²)。\n\n「a, b 是常數」與「ε>0」是必要設定；僅說 f(n) 成長較快仍不夠，還須多一個固定正次方及上述規則性條件。原選項的 O 記號與上標文字未表達這個下界方向，不能拿它代替 Ω(n^(p+ε))。現有答案與原選項保留，此處指出公式方向及條件的差異。","warn":false,"opts":["a, b 是常數","f(n) 為 O(nˡᵒᵍᵇ⁽ᵃ⁾(a - ε))","ε > 0","f(n) 成長較快"],"bookmarkId":"L3-035","exact":false,"sources":["algorithm-analysis"],"answerProvided":true,"choiceKey":"ABC","aliases":[],"imageKeys":[],"images":[],"stem":"大師定理 Case 3 的條件包含？","options":["a, b 是常數","f(n) 為 O(nˡᵒᵍᵇ⁽ᵃ⁾(a - ε))","ε > 0","f(n) 成長較快"],"answer":"A、B、C","explanation":"對 T(n)=aT(n/b)+f(n)，先令 p=log_b a。Case 3 要求 a≥1、b>1 為常數，且存在 ε>0，使 f(n)=Ω(n^(p+ε))；還需規則性條件：存在 c<1，使 a·f(n/b)≤c·f(n) 對足夠大的 n 成立，才能得到 T(n)=Θ(f(n))。\n\n例如 2T(n/2)+n²，p=1，n² 比 n 多一個正次方，且 2(n/2)²=n²/2，符合規則性條件，因此為 Θ(n²)。\n\n「a, b 是常數」與「ε>0」是必要設定；僅說 f(n) 成長較快仍不夠，還須多一個固定正次方及上述規則性條件。原選項的 O 記號與上標文字未表達這個下界方向，不能拿它代替 Ω(n^(p+ε))。現有答案與原選項保留，此處指出公式方向及條件的差異。","translation":"","optionTranslations":[],"note":"","originalAnswer":"f(n) 成長速度大於 n^(logb(a))、存在常數 epsilon > 0、滿足規則性條件 (regularity condition)"}','{"category":"大師定理","type":"多選題","q":"大師定理 Case 3 的條件包含？","a":"A、B、C","ex":"令 p=log_b a。Case 3 必須存在 ε>0，使 f(n)=Ω(n^(p+ε))，並且有常數 c<1，使 a f(n/b)≤c f(n) 對足夠大的 n 成立（regularity condition）。這表示往下一層的工作按固定比例減少，成本由根部主導，才可得 T(n)=Θ(f(n))。只說 f「比較大」不夠。","warn":false,"opts":["a, b 是常數","f(n) 為 O(nˡᵒᵍᵇ⁽ᵃ⁾(a - ε))","ε > 0","f(n) 成長較快"],"bookmarkId":"L3-035","exact":false,"sources":["algorithm-analysis"],"answerProvided":true,"choiceKey":"ABC","aliases":[],"imageKeys":[],"images":[],"stem":"大師定理 Case 3 的條件包含？","options":["a, b 是常數","f(n) 為 O(nˡᵒᵍᵇ⁽ᵃ⁾(a - ε))","ε > 0","f(n) 成長較快"],"answer":"A、B、C","explanation":"令 p=log_b a。Case 3 必須存在 ε>0，使 f(n)=Ω(n^(p+ε))，並且有常數 c<1，使 a f(n/b)≤c f(n) 對足夠大的 n 成立（regularity condition）。這表示往下一層的工作按固定比例減少，成本由根部主導，才可得 T(n)=Θ(f(n))。只說 f「比較大」不夠。","translation":"","optionTranslations":[],"note":"","originalAnswer":"f(n) 成長速度大於 n^(logb(a))、存在常數 epsilon > 0、滿足規則性條件 (regularity condition)"}','e1e2e4ac18b8ebb28714875f6ef99d922d83df36b6def6ab3540c7e4c6d8912c','update','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變','owner-requested',1795706845211 WHERE COALESCE((SELECT MAX(revision) FROM builtin_question_edits WHERE course='algorithms' AND question_id='L3-035'),0)=4 AND EXISTS (SELECT 1 FROM builtin_question_edits WHERE id='bfed23ad-9af9-40b6-be11-677b224bf8d2' AND data='{"category":"大師定理","type":"多選題","q":"大師定理 Case 3 的條件包含？","a":"A、B、C","ex":"令 p=log_b a。Case 3 必須存在 ε>0，使 f(n)=Ω(n^(p+ε))，並且有常數 c<1，使 a f(n/b)≤c f(n) 對足夠大的 n 成立（regularity condition）。這表示往下一層的工作按固定比例減少，成本由根部主導，才可得 T(n)=Θ(f(n))。只說 f「比較大」不夠。","warn":false,"opts":["a, b 是常數","f(n) 為 O(nˡᵒᵍᵇ⁽ᵃ⁾(a - ε))","ε > 0","f(n) 成長較快"],"bookmarkId":"L3-035","exact":false,"sources":["algorithm-analysis"],"answerProvided":true,"choiceKey":"ABC","aliases":[],"imageKeys":[],"images":[],"stem":"大師定理 Case 3 的條件包含？","options":["a, b 是常數","f(n) 為 O(nˡᵒᵍᵇ⁽ᵃ⁾(a - ε))","ε > 0","f(n) 成長較快"],"answer":"A、B、C","explanation":"令 p=log_b a。Case 3 必須存在 ε>0，使 f(n)=Ω(n^(p+ε))，並且有常數 c<1，使 a f(n/b)≤c f(n) 對足夠大的 n 成立（regularity condition）。這表示往下一層的工作按固定比例減少，成本由根部主導，才可得 T(n)=Θ(f(n))。只說 f「比較大」不夠。","translation":"","optionTranslations":[],"note":"","originalAnswer":"f(n) 成長速度大於 n^(logb(a))、存在常數 epsilon > 0、滿足規則性條件 (regularity condition)"}');
INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT '210fc16e-9e2d-4b39-8e58-0b6a9b870dec','algorithms','L7-2514',2,'{"category":"最小值與最大值","type":"填空題","q":"同時尋找最大與最小值時，配對比較法總共需要 ____________ 次比較 (請用小寫英文與分數型態回答)","a":"3n/2","opts":[],"ex":"配對比較法先把兩個元素互相比較，再把較小者與目前最小值比較、較大者與目前最大值比較，所以每處理一對通常花三次比較，主要項為 3n/2。\n\n偶數 n：先比較第一對來建立最大、最小值，花 1 次；剩下 (n−2)/2 對各花 3 次，共 1+3(n−2)/2=3n/2−2。\n奇數 n：用第一個元素同時初始化兩個極值，不需比較；剩下 (n−1)/2 對各花 3 次，共 3(n−1)/2。\n\n例如 n=6 需 7 次，n=5 需 6 次。n≥2 可統一寫成 ⌈3n/2⌉−2。現有填答 3n/2 表示主要項，與精確總次數的常數項不同；n=1 時則不需比較。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2514","sourceId":"2514","sourceIds":["2514"],"sourceNumber":47,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"困難","aliases":[],"imageKeys":[],"images":[],"stem":"同時尋找最大與最小值時，配對比較法總共需要 ____________ 次比較 (請用小寫英文與分數型態回答)","options":[],"answer":"3n/2","explanation":"配對比較法先把兩個元素互相比較，再把較小者與目前最小值比較、較大者與目前最大值比較，所以每處理一對通常花三次比較，主要項為 3n/2。\n\n偶數 n：先比較第一對來建立最大、最小值，花 1 次；剩下 (n−2)/2 對各花 3 次，共 1+3(n−2)/2=3n/2−2。\n奇數 n：用第一個元素同時初始化兩個極值，不需比較；剩下 (n−1)/2 對各花 3 次，共 3(n−1)/2。\n\n例如 n=6 需 7 次，n=5 需 6 次。n≥2 可統一寫成 ⌈3n/2⌉−2。現有填答 3n/2 表示主要項，與精確總次數的常數項不同；n=1 時則不需比較。","translation":"","optionTranslations":[],"note":""}','{"category":"最小值與最大值","type":"填空題","q":"同時尋找最大與最小值時，配對比較法總共需要 ____________ 次比較 (請用小寫英文與分數型態回答)","a":"3n/2","opts":[],"ex":"填 3n/2，這是主要項的近似。精確計數依奇偶不同：偶數 n 先比較第一對，之後每對三次，共 3n/2−2；奇數 n 用第一個值初始化兩個極值，之後共 3(n−1)/2 次。因此 n≥2 時可統一寫成 ⌈3n/2⌉−2；n=1 時零次。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2514","sourceId":"2514","sourceIds":["2514"],"sourceNumber":47,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"困難","aliases":[],"imageKeys":[],"images":[],"stem":"同時尋找最大與最小值時，配對比較法總共需要 ____________ 次比較 (請用小寫英文與分數型態回答)","options":[],"answer":"3n/2","explanation":"填 3n/2，這是主要項的近似。精確計數依奇偶不同：偶數 n 先比較第一對，之後每對三次，共 3n/2−2；奇數 n 用第一個值初始化兩個極值，之後共 3(n−1)/2 次。因此 n≥2 時可統一寫成 ⌈3n/2⌉−2；n=1 時零次。","translation":"","optionTranslations":[],"note":""}','b29f4f10a6399ad4c9a770a17addeff7d5f696796a304c85604a49a1fdf9fb62','update','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變','owner-requested',1795706845211 WHERE COALESCE((SELECT MAX(revision) FROM builtin_question_edits WHERE course='algorithms' AND question_id='L7-2514'),0)=1 AND EXISTS (SELECT 1 FROM builtin_question_edits WHERE id='77906046-ab12-4fbd-90cc-199ec92303ce' AND data='{"category":"最小值與最大值","type":"填空題","q":"同時尋找最大與最小值時，配對比較法總共需要 ____________ 次比較 (請用小寫英文與分數型態回答)","a":"3n/2","opts":[],"ex":"填 3n/2，這是主要項的近似。精確計數依奇偶不同：偶數 n 先比較第一對，之後每對三次，共 3n/2−2；奇數 n 用第一個值初始化兩個極值，之後共 3(n−1)/2 次。因此 n≥2 時可統一寫成 ⌈3n/2⌉−2；n=1 時零次。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2514","sourceId":"2514","sourceIds":["2514"],"sourceNumber":47,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"困難","aliases":[],"imageKeys":[],"images":[],"stem":"同時尋找最大與最小值時，配對比較法總共需要 ____________ 次比較 (請用小寫英文與分數型態回答)","options":[],"answer":"3n/2","explanation":"填 3n/2，這是主要項的近似。精確計數依奇偶不同：偶數 n 先比較第一對，之後每對三次，共 3n/2−2；奇數 n 用第一個值初始化兩個極值，之後共 3(n−1)/2 次。因此 n≥2 時可統一寫成 ⌈3n/2⌉−2；n=1 時零次。","translation":"","optionTranslations":[],"note":""}');
INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT '5f891d82-147a-4ff9-95fc-94cfa520ca48','algorithms','L7-2497',1,'{"category":"Randomized-Select","type":"多選題","q":"Randomized-Select 最壞情況的發生條件？","a":"A、B","opts":["A. pivot 總選擇到最大值或最小值","B. 陣列已幾乎排序完成","C. 陣列元素全部相同","D. pivot 總選擇到中位數"],"ex":"Randomized-Select 只繼續處理目標所在的一側。「pivot 總選擇到最大值或最小值」表示樞紐反覆落在極端，且目標一直留在其餘 n−1 個元素，掃描工作為 n+(n−1)+…+1=Θ(n²)，這是最壞情況的形成方式。\n\n「陣列已幾乎排序完成」容易讓固定選端點的策略退化，但均勻隨機選樞紐時，單靠幾乎有序並不能保證退化。「陣列元素全部相同」的影響取決於分割實作：某些二向分割仍可能退化，三向分割可一次處理相同值。「pivot 總選擇到中位數」則讓剩餘規模近似減半，總工作為 n+n/2+n/4+…=Θ(n)。\n\n現有答案包含幾乎排序的選項；該條件與隨機選樞紐的最壞保證有差異，不能將固定端點策略的結論直接套用。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2497","sourceId":"2497","sourceIds":["2497"],"sourceNumber":30,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"困難","aliases":[],"imageKeys":[],"images":[],"explanation":"Randomized-Select 只繼續處理目標所在的一側。「pivot 總選擇到最大值或最小值」表示樞紐反覆落在極端，且目標一直留在其餘 n−1 個元素，掃描工作為 n+(n−1)+…+1=Θ(n²)，這是最壞情況的形成方式。\n\n「陣列已幾乎排序完成」容易讓固定選端點的策略退化，但均勻隨機選樞紐時，單靠幾乎有序並不能保證退化。「陣列元素全部相同」的影響取決於分割實作：某些二向分割仍可能退化，三向分割可一次處理相同值。「pivot 總選擇到中位數」則讓剩餘規模近似減半，總工作為 n+n/2+n/4+…=Θ(n)。\n\n現有答案包含幾乎排序的選項；該條件與隨機選樞紐的最壞保證有差異，不能將固定端點策略的結論直接套用。"}','{"category":"Randomized-Select","type":"多選題","q":"Randomized-Select 最壞情況的發生條件？","a":"A、B","opts":["A. pivot 總選擇到最大值或最小值","B. 陣列已幾乎排序完成","C. 陣列元素全部相同","D. pivot 總選擇到中位數"],"ex":"來源答案保留 A、B，但 B 需要更正觀念。真正造成 Randomized-Select 最壞 Θ(n²) 的條件，是樞紐沿目標遞迴路徑反覆落在極端位置（A）。輸入幾乎排序好（B）本身不會讓隨機樞紐必定變差；它常使固定選端點的版本退化。若允許相等元素，全部相同的資料也可能讓某些二向分割退化，但本章通常假設元素相異。樞紐一直接近中位數則會得到線性時間。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2497","sourceId":"2497","sourceIds":["2497"],"sourceNumber":30,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"困難","aliases":[],"imageKeys":[],"images":[]}','82f72235dc17ccfd99ab2a96cfceab75e598eeddffa9b4ea90750c90ca8c4a90','update','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變','owner-requested',1795706845211 WHERE COALESCE((SELECT MAX(revision) FROM builtin_question_edits WHERE course='algorithms' AND question_id='L7-2497'),0)=0;
INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT 'c4b2aa61-6731-4243-9d35-c80df7498404','algorithms','L7-2505',1,'{"category":"Randomized-Select","type":"多選題","q":"Randomized-Select 中，Randomized-Partition 的意義？","a":"A、D","opts":["A. 隨機選擇 pivot 以避免最壞情況","B. 強制陣列排序","C. 確保 pivot 永遠在中間","D. 加速 Partition 的執行"],"ex":"Randomized-Partition 先隨機選樞紐，再依它把元素分到較小、較大的區域。隨機化使每個位置都有機會被選到，降低固定端點策略在特殊輸入上反覆產生極端分割的風險，但仍可能連續抽到不好的樞紐。\n\n「隨機選擇 pivot 以避免最壞情況」應理解為降低風險，並不保證消除最壞情況。「強制陣列排序」不成立，分割只確立大小區域；「確保 pivot 永遠在中間」也不成立，隨機值可能偏大或偏小。\n\n一次 Partition 仍須掃描目前範圍，時間為 Θ(n)。現有答案包含「加速 Partition 的執行」，但嚴格說改善的是整體選擇流程的期望效率，單次分割的漸近成本沒有因此下降。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2505","sourceId":"2505","sourceIds":["2505"],"sourceNumber":38,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"困難","aliases":[],"imageKeys":[],"images":[],"explanation":"Randomized-Partition 先隨機選樞紐，再依它把元素分到較小、較大的區域。隨機化使每個位置都有機會被選到，降低固定端點策略在特殊輸入上反覆產生極端分割的風險，但仍可能連續抽到不好的樞紐。\n\n「隨機選擇 pivot 以避免最壞情況」應理解為降低風險，並不保證消除最壞情況。「強制陣列排序」不成立，分割只確立大小區域；「確保 pivot 永遠在中間」也不成立，隨機值可能偏大或偏小。\n\n一次 Partition 仍須掃描目前範圍，時間為 Θ(n)。現有答案包含「加速 Partition 的執行」，但嚴格說改善的是整體選擇流程的期望效率，單次分割的漸近成本沒有因此下降。"}','{"category":"Randomized-Select","type":"多選題","q":"Randomized-Select 中，Randomized-Partition 的意義？","a":"A、D","opts":["A. 隨機選擇 pivot 以避免最壞情況","B. 強制陣列排序","C. 確保 pivot 永遠在中間","D. 加速 Partition 的執行"],"ex":"來源答案保留 A、D，但兩項都要注意措辭。隨機挑選樞紐能降低固定規則反覆遇到壞分割的風險，改善整體選擇／快速排序的期望表現；它不能完全消除最壞情況，因此 A 的『避免』不能當成絕對保證。單次 Partition 仍需 Θ(n) 掃描，D 若指讓 Partition 本身漸近變快並不正確，只有寬鬆解讀為改善整體期望效率才說得通。隨機樞紐也不保證完整排序或剛好選到中位數。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2505","sourceId":"2505","sourceIds":["2505"],"sourceNumber":38,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"困難","aliases":[],"imageKeys":[],"images":[]}','2796dac83dac8749ce3ba90149fd8d3c8e8ec4cac60048d3cf6a795262a11afb','update','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變','owner-requested',1795706845211 WHERE COALESCE((SELECT MAX(revision) FROM builtin_question_edits WHERE course='algorithms' AND question_id='L7-2505'),0)=0;
INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT 'cf6a4b21-bf40-43c5-8614-d2981b950bbe','algorithms','L7-2509',2,'{"category":"Randomized-Select","type":"填空題","q":"Randomized-Select 的平均時間複雜度為 ____________ (請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,})","a":"O(n)","opts":[],"ex":"Randomized-Select 每次先花線性時間分割，再只遞迴到目標所在的一側。隨機樞紐讓剩餘問題的規模在期望上持續縮小，整體期望時間為 Θ(n)，因此現有填答 O(n) 也是有效的線性上界。\n\n可用近似均衡的路徑理解：n+n/2+n/4+…≤2n。但隨機化不保證每次均衡；若反覆只排除一個元素，則 n+(n−1)+…=Θ(n²)。期望線性與最壞平方是不同保證，不能互換。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2509","sourceId":"2509","sourceIds":["2509"],"sourceNumber":42,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"簡單","aliases":[],"imageKeys":[],"images":[],"stem":"Randomized-Select 的平均時間複雜度為 ____________ (請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,})","options":[],"answer":"O(n)","explanation":"Randomized-Select 每次先花線性時間分割，再只遞迴到目標所在的一側。隨機樞紐讓剩餘問題的規模在期望上持續縮小，整體期望時間為 Θ(n)，因此現有填答 O(n) 也是有效的線性上界。\n\n可用近似均衡的路徑理解：n+n/2+n/4+…≤2n。但隨機化不保證每次均衡；若反覆只排除一個元素，則 n+(n−1)+…=Θ(n²)。期望線性與最壞平方是不同保證，不能互換。","translation":"","optionTranslations":[],"note":""}','{"category":"Randomized-Select","type":"填空題","q":"Randomized-Select 的平均時間複雜度為 ____________ (請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,})","a":"O(n)","opts":[],"ex":"填 O(n)。Randomized-Select 的期望時間為 Θ(n)：分割本身線性，之後只繼續處理目標所在的一邊。隨機性使平均剩餘工作量受控制；這和最壞 Θ(n²) 是不同的保證。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2509","sourceId":"2509","sourceIds":["2509"],"sourceNumber":42,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"簡單","aliases":[],"imageKeys":[],"images":[],"stem":"Randomized-Select 的平均時間複雜度為 ____________ (請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,})","options":[],"answer":"O(n)","explanation":"填 O(n)。Randomized-Select 的期望時間為 Θ(n)：分割本身線性，之後只繼續處理目標所在的一邊。隨機性使平均剩餘工作量受控制；這和最壞 Θ(n²) 是不同的保證。","translation":"","optionTranslations":[],"note":""}','3acc651204fb23d12a0411edf8366d69b817be6bc849fd1c67981aa43a6f6a19','update','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變','owner-requested',1795706845211 WHERE COALESCE((SELECT MAX(revision) FROM builtin_question_edits WHERE course='algorithms' AND question_id='L7-2509'),0)=1 AND EXISTS (SELECT 1 FROM builtin_question_edits WHERE id='547c953d-eda4-4fe8-b4f0-d063974dbc4f' AND data='{"category":"Randomized-Select","type":"填空題","q":"Randomized-Select 的平均時間複雜度為 ____________ (請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,})","a":"O(n)","opts":[],"ex":"填 O(n)。Randomized-Select 的期望時間為 Θ(n)：分割本身線性，之後只繼續處理目標所在的一邊。隨機性使平均剩餘工作量受控制；這和最壞 Θ(n²) 是不同的保證。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2509","sourceId":"2509","sourceIds":["2509"],"sourceNumber":42,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"簡單","aliases":[],"imageKeys":[],"images":[],"stem":"Randomized-Select 的平均時間複雜度為 ____________ (請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,})","options":[],"answer":"O(n)","explanation":"填 O(n)。Randomized-Select 的期望時間為 Θ(n)：分割本身線性，之後只繼續處理目標所在的一邊。隨機性使平均剩餘工作量受控制；這和最壞 Θ(n²) 是不同的保證。","translation":"","optionTranslations":[],"note":""}');
INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT '7a830d4a-ec93-4cdc-b413-8f23309b5154','algorithms','L7-2517',3,'{"category":"Randomized-Select","type":"填空題","q":"中位數選擇法（Median Order / Quickselect） 假設我們有以下 18 個未排序的整數： 42, 17, 89, 8, 55, 23, 71, 94, 12, 63, 31, 76, 5, 50, 82, 29, 66, 37 當他進行第一輪分割後 要找的目標在比選中的基準值 (Pivot) 大的組別裡面的第幾個 ____________ 比基準值 (Pivot) 小的有幾個 ____________","a":"5/11","opts":[],"ex":"以樞紐 63 分割，較小的數為 42、17、8、55、23、12、31、5、50、29、37，共 11 個；較大的數為 89、71、94、76、82、66，共 6 個。所以樞紐是原陣列第 12 小，第二格的 11 可以直接核對。\n\n若原目標是第 i 小，且 i>12，進入右側後要找第 i−12 小。要使第一格為 5，必須原本找第 17 小；右側排序為 66、71、76、82、89、94，第 5 小為 89。\n\n現有答案 5/11 維持不變，但原題沒有明列樞紐選法及目標順位，無法唯一推得第一格。若題意是十八個數的中位數，目標第 9、10 小都在 63 的左側，與「在較大組」不同。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2517","sourceId":"2517","sourceIds":["2517"],"sourceNumber":50,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"簡單","aliases":[],"imageKeys":[],"images":[],"stem":"中位數選擇法（Median Order / Quickselect） 假設我們有以下 18 個未排序的整數： 42, 17, 89, 8, 55, 23, 71, 94, 12, 63, 31, 76, 5, 50, 82, 29, 66, 37 當他進行第一輪分割後 要找的目標在比選中的基準值 (Pivot) 大的組別裡面的第幾個 ____________ 比基準值 (Pivot) 小的有幾個 ____________","options":[],"answer":"5/11","explanation":"以樞紐 63 分割，較小的數為 42、17、8、55、23、12、31、5、50、29、37，共 11 個；較大的數為 89、71、94、76、82、66，共 6 個。所以樞紐是原陣列第 12 小，第二格的 11 可以直接核對。\n\n若原目標是第 i 小，且 i>12，進入右側後要找第 i−12 小。要使第一格為 5，必須原本找第 17 小；右側排序為 66、71、76、82、89、94，第 5 小為 89。\n\n現有答案 5/11 維持不變，但原題沒有明列樞紐選法及目標順位，無法唯一推得第一格。若題意是十八個數的中位數，目標第 9、10 小都在 63 的左側，與「在較大組」不同。","translation":"","optionTranslations":[],"note":"","originalAnswer":"5 / 11"}','{"category":"Randomized-Select","type":"填空題","q":"中位數選擇法（Median Order / Quickselect） 假設我們有以下 18 個未排序的整數： 42, 17, 89, 8, 55, 23, 71, 94, 12, 63, 31, 76, 5, 50, 82, 29, 66, 37 當他進行第一輪分割後 要找的目標在比選中的基準值 (Pivot) 大的組別裡面的第幾個 ____________ 比基準值 (Pivot) 小的有幾個 ____________","a":"5/11","opts":[],"ex":"來源依序填 5、11。假設樞紐取 63，左側十一個、樞紐為第十二小；若原目標為全體第十七小，進入右側後應找第 17−12=5 小，即 89。因此第二格十一可由數值比較確認；第一格五還需要原目標 i=17。題目未提供 i，不能無條件推得五；若求十八個數的中位數，目標在左側而不是右側。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2517","sourceId":"2517","sourceIds":["2517"],"sourceNumber":50,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"簡單","aliases":[],"imageKeys":[],"images":[],"stem":"中位數選擇法（Median Order / Quickselect） 假設我們有以下 18 個未排序的整數： 42, 17, 89, 8, 55, 23, 71, 94, 12, 63, 31, 76, 5, 50, 82, 29, 66, 37 當他進行第一輪分割後 要找的目標在比選中的基準值 (Pivot) 大的組別裡面的第幾個 ____________ 比基準值 (Pivot) 小的有幾個 ____________","options":[],"answer":"5/11","explanation":"來源依序填 5、11。假設樞紐取 63，左側十一個、樞紐為第十二小；若原目標為全體第十七小，進入右側後應找第 17−12=5 小，即 89。因此第二格十一可由數值比較確認；第一格五還需要原目標 i=17。題目未提供 i，不能無條件推得五；若求十八個數的中位數，目標在左側而不是右側。","translation":"","optionTranslations":[],"note":"","originalAnswer":"5 / 11"}','f54cb801a9f4e3932af7735eaa17a3d31ca6fe2269be4ffdea67c1aa63815815','update','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變','owner-requested',1795706845212 WHERE COALESCE((SELECT MAX(revision) FROM builtin_question_edits WHERE course='algorithms' AND question_id='L7-2517'),0)=2 AND EXISTS (SELECT 1 FROM builtin_question_edits WHERE id='e03ad237-3d53-4196-a582-2156acc43cfa' AND data='{"category":"Randomized-Select","type":"填空題","q":"中位數選擇法（Median Order / Quickselect） 假設我們有以下 18 個未排序的整數： 42, 17, 89, 8, 55, 23, 71, 94, 12, 63, 31, 76, 5, 50, 82, 29, 66, 37 當他進行第一輪分割後 要找的目標在比選中的基準值 (Pivot) 大的組別裡面的第幾個 ____________ 比基準值 (Pivot) 小的有幾個 ____________","a":"5/11","opts":[],"ex":"來源依序填 5、11。假設樞紐取 63，左側十一個、樞紐為第十二小；若原目標為全體第十七小，進入右側後應找第 17−12=5 小，即 89。因此第二格十一可由數值比較確認；第一格五還需要原目標 i=17。題目未提供 i，不能無條件推得五；若求十八個數的中位數，目標在左側而不是右側。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2517","sourceId":"2517","sourceIds":["2517"],"sourceNumber":50,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"簡單","aliases":[],"imageKeys":[],"images":[],"stem":"中位數選擇法（Median Order / Quickselect） 假設我們有以下 18 個未排序的整數： 42, 17, 89, 8, 55, 23, 71, 94, 12, 63, 31, 76, 5, 50, 82, 29, 66, 37 當他進行第一輪分割後 要找的目標在比選中的基準值 (Pivot) 大的組別裡面的第幾個 ____________ 比基準值 (Pivot) 小的有幾個 ____________","options":[],"answer":"5/11","explanation":"來源依序填 5、11。假設樞紐取 63，左側十一個、樞紐為第十二小；若原目標為全體第十七小，進入右側後應找第 17−12=5 小，即 89。因此第二格十一可由數值比較確認；第一格五還需要原目標 i=17。題目未提供 i，不能無條件推得五；若求十八個數的中位數，目標在左側而不是右側。","translation":"","optionTranslations":[],"note":"","originalAnswer":"5 / 11"}');
INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT 'bc52a2b4-891d-49cd-82c1-ecc8e1915399','algorithms','L7-2525',1,'{"category":"Randomized-Select","type":"填空題","q":"Randomized-Select 演算法在＿＿＿情況下表現最快","a":"average","opts":[],"ex":"Randomized-Select 的期望時間為 Θ(n)，現有填答是 average。每次先做線性分割，再沿目標所在的一側繼續，因此只要剩餘問題規模在期望上受控制，總工作便維持線性。\n\n要區分三種分析：最好情況是第一輪樞紐恰好命中目標，仍需一次 Θ(n) 掃描；期望情況也是 Θ(n)；最壞情況反覆只排除一個元素，成本為 n+(n−1)+…=Θ(n²)。因此題幹的「最快」若指最好情況，英文應是 best，而不是 average。原答案保留，這個用語差異需另外辨認。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2525","sourceId":"2525","sourceIds":["2525"],"sourceNumber":58,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"困難","aliases":[],"imageKeys":[],"images":[],"explanation":"Randomized-Select 的期望時間為 Θ(n)，現有填答是 average。每次先做線性分割，再沿目標所在的一側繼續，因此只要剩餘問題規模在期望上受控制，總工作便維持線性。\n\n要區分三種分析：最好情況是第一輪樞紐恰好命中目標，仍需一次 Θ(n) 掃描；期望情況也是 Θ(n)；最壞情況反覆只排除一個元素，成本為 n+(n−1)+…=Θ(n²)。因此題幹的「最快」若指最好情況，英文應是 best，而不是 average。原答案保留，這個用語差異需另外辨認。"}','{"category":"Randomized-Select","type":"填空題","q":"Randomized-Select 演算法在＿＿＿情況下表現最快","a":"average","opts":[],"ex":"填 average，對應課本強調的平均／期望線性時間。不過『在平均情況下最快』並不是嚴格的複雜度說法：最好情況也是 Θ(n)，例如一次分割後樞紐剛好命中目標；平均／期望 Θ(n)，最壞 Θ(n²)。此題應用來記住平均效率，不應把 average 當成 best case 的同義詞。","warn":false,"answerProvided":true,"verified":false,"bookmarkId":"L7-2525","sourceId":"2525","sourceIds":["2525"],"sourceNumber":58,"sources":["algorithms-l7-peer"],"sourceFile":"content/algorithms-l7-peer-20261029.json","difficulty":"困難","aliases":[],"imageKeys":[],"images":[]}','65e6395e185fea06ea295cbf144a14817a813390f79e8d17baca1a4da51c5186','update','逐單元重寫解析：移除權威用語，補充推導與條件差異；題目及答案不變','owner-requested',1795706845212 WHERE COALESCE((SELECT MAX(revision) FROM builtin_question_edits WHERE course='algorithms' AND question_id='L7-2525'),0)=0;
